package net.battlespades.bot;
import java.util.*;
import java.util.function.DoubleSupplier;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotMessages.*;
import static net.battlespades.bot.BotState.*;
import static net.battlespades.bot.BotVectors.*;

/** Short-lived, epoch/life-fenced proposals with bounded diagnostics and non-reversing crowd separation. */
final class BrainIntents {
    private final DoubleSupplier clock;BrainIntents(DoubleSupplier clock){this.clock=Objects.requireNonNull(clock);}
    Intent emit(Perception frame,BotBrainState state,Movement movement,Look look,int tool,Action action,Priority priority,boolean secondary,boolean zoom,Vector goal,List<Vector> path,String role,boolean adjust){if(adjust)movement=crowd(frame,movement,action);double emitted=Math.max(clock.getAsDouble(),frame.createdAt());int life=frame.players().stream().filter(p->p.id()==frame.observerId()&&p.generation()==frame.observerGeneration()).mapToInt(Player::lifeId).findFirst().orElse(-1);return new Intent(frame.observerId(),frame.observerGeneration(),frame.frameId(),frame.mapEpoch(),frame.modeEpoch(),frame.topologyVersion(),emitted,emitted+.4,movement,look,tool,action,priority,secondary,zoom,goal,path,role,life,state==null?List.of():diagnostics(state,frame.createdAt()));}
    static Vector gaze(BotBrainState s,Player p,double now){var contact=s.contactPosition;if(contact!=null&&now-(s.contactUntil-4)>=0&&now-(s.contactUntil-4)<=2&&flat(contact,p.position())>3)return contact;var rest=PathFollowing.gazeWaypoint(s.route,s.routeIndex,p.position());if(rest!=null){s.travelGaze=rest;s.travelGazeAt=now;}else if(s.travelGaze!=null&&now-s.travelGazeAt<=1.5&&flat(s.travelGaze,p.position())>3)return s.travelGaze;return rest;}
    static double rounded(double value){return RecoveryPlanning.rounded(value,3);}
    static List<Diagnostic> diagnostics(BotBrainState s,double now){var r=new ArrayList<Diagnostic>();var search=s.corridorSearch;r.add(new Diagnostic("corridor_expansions",search==null?-1:search.expansions()));r.add(new Diagnostic("corridor_done",search==null?null:search.done()));r.add(new Diagnostic("corridor_remaining",Math.max(0,s.corridor.size()-s.corridorIndex)));r.add(new Diagnostic("corridor_yield_local",s.corridorYieldLocal));r.add(new Diagnostic("corridor_endpoint_failure",s.corridorFailedGoal!=null));r.add(new Diagnostic("escape_goal",s.escapeGoal));r.add(new Diagnostic("escape_query_index",s.escapeSearch==null?-1:s.escapeSearch.index()));r.add(new Diagnostic("escape_attempts",s.escapeAttempts));r.add(new Diagnostic("step_note",s.stepNote));r.add(new Diagnostic("goal_progress_age",rounded(Math.max(0,now-s.goalProgressAt))));r.add(new Diagnostic("coverage_age",rounded(Math.max(0,now-s.navigationCoverageAt))));r.add(new Diagnostic("route_index",s.routeIndex));r.add(new Diagnostic("route_remaining",Math.max(0,s.route.size()-s.routeIndex)));r.add(new Diagnostic("planning_results",s.planningResults.size()));r.add(new Diagnostic("planning_wait",s.planningWaitAt!=null));r.add(new Diagnostic("blocked_edges",s.blockedEdges.size()));r.add(new Diagnostic("support_no_progress_time",rounded(s.supportNoProgressTime)));r.add(new Diagnostic("support_progress_anchor",s.supportProgressAnchor));r.add(new Diagnostic("support_failed_goal",s.supportFailedGoal));r.add(new Diagnostic("support_failure_age",s.supportFailedGoal==null?null:rounded(Math.max(0,now-s.supportFailureAt))));r.add(new Diagnostic("support_escape_attempted",s.supportEscapeAttempted));return List.copyOf(r);}
    static Movement direction(Movement m,Vector v){return new Movement(v,m.jump(),m.crouch(),m.sneak(),m.sprint(),m.affordance(),m.jetpackThrust(),m.travelSource(),m.travelWaypoint(),m.gazeWaypoint(),m.walkDrop());}
    static Movement crowd(Perception f,Movement m,Action action){if(!Set.of(Affordance.WALK,Affordance.CROUCH,Affordance.SWIM).contains(m.affordance())||Set.of(ActionKind.BUILD,ActionKind.BUILD_LINE,ActionKind.MINE,ActionKind.PLACE_PREFAB,ActionKind.DEPLOY).contains(action.kind()))return m;var observer=f.players().stream().filter(p->p.id()==f.observerId()&&p.generation()==f.observerGeneration()).findFirst().orElse(null);if(observer==null)return m;double x=m.direction().x(),y=m.direction().y(),length=Math.hypot(x,y);if(length<=1e-6)return m;x/=length;y/=length;double rx=0,ry=0;int neighbors=0;for(var p:f.players()){if(!p.bot()||!p.alive()||!p.spawned()||p.id()==observer.id()||p.team()!=observer.team()||Math.abs(p.position().z()-observer.position().z())>2.25)continue;double dx=observer.position().x()-p.position().x(),dy=observer.position().y()-p.position().y(),distance=Math.hypot(dx,dy);if(distance>=1.5)continue;double ux,uy;if(distance<=1e-4){double sign=observer.id()<p.id()?1:-1;ux=-y*sign;uy=x*sign;}else{ux=dx/distance;uy=dy/distance;}double strength=1-distance/1.5;rx+=ux*strength;ry+=uy*strength;neighbors++;}if(neighbors<=0)return m;double cx=x+rx*3,cy=y+ry*3,combined=Math.hypot(cx,cy);if(combined<=1e-6)return m;double ux=cx/combined,uy=cy/combined,forward=ux*x+uy*y;if(forward<.35){double lx=ux-forward*x,ly=uy-forward*y,ll=Math.hypot(lx,ly);if(ll>1e-6){lx/=ll;ly/=ll;double scale=Math.sqrt(1-.35*.35);ux=x*.35+lx*scale;uy=y*.35+ly*scale;}else{ux=x;uy=y;}}double scale=Math.min(1,length);return direction(m,new Vector(ux*scale,uy*scale,0));}
}
